{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello Akash आपकी New Holland tractor toy की request IndiaMART पर raised है।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "क्या करने की?"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "बस आपकी requirement के बारे में कुछ जानकारी चाहिए थी ताकि हम आपको सही seller से connect कर सकें।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "चलिए अब brand के बारे में बात कर लेते हैं।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए Mahindra या कुछ और?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "क्या बात है?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "नहीं नहीं वो अलग से है।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "ठीक है मैंने note कर लिया है।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "क्या आप इस product के बारे में कोई और details या specification share करना चाहेंगे?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "कौनसी detail?"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "मेरा मतलब था कि क्या आप इस product के बारे में कुछ और बताना चाहेंगे जैसे कोई खास feature या size?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "जैसे कितने का पड़ेगा ये?"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "जी मैं समझ गया।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपकी details note कर ली गई हैं और जल्द ही एक seller आपसे contact करेंगे।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
